UPDATE geo_region SET name_uz_lat = 'Andijon viloyati',     name_ru = 'Андижанская область'      WHERE full_code = 'UZ-01';
UPDATE geo_region SET name_uz_lat = 'Buxoro viloyati',      name_ru = 'Бухарская область'         WHERE full_code = 'UZ-02';
UPDATE geo_region SET name_uz_lat = E'Farg''ona viloyati',  name_ru = 'Ферганская область'        WHERE full_code = 'UZ-03';
UPDATE geo_region SET name_uz_lat = 'Jizzax viloyati',      name_ru = 'Джизакская область'        WHERE full_code = 'UZ-15';
UPDATE geo_region SET name_uz_lat = 'Namangan viloyati',    name_ru = 'Наманганская область'      WHERE full_code = 'UZ-06';
UPDATE geo_region SET name_uz_lat = 'Navoiy viloyati',      name_ru = 'Навоийская область'        WHERE full_code = 'UZ-07';
UPDATE geo_region SET name_uz_lat = 'Qashqadaryo viloyati', name_ru = 'Кашкадарьинская область'   WHERE full_code = 'UZ-08';
UPDATE geo_region SET name_uz_lat = E'Qoraqalpog''iston Respublikasi', name_ru = 'Республика Каракалпакстан' WHERE full_code = 'UZ-09';
UPDATE geo_region SET name_uz_lat = 'Samarqand viloyati',   name_ru = 'Самаркандская область'     WHERE full_code = 'UZ-10';
UPDATE geo_region SET name_uz_lat = 'Sirdaryo viloyati',    name_ru = 'Сырдарьинская область'     WHERE full_code = 'UZ-16';
UPDATE geo_region SET name_uz_lat = 'Surxondaryo viloyati', name_ru = 'Сурхандарьинская область'  WHERE full_code = 'UZ-12';
UPDATE geo_region SET name_uz_lat = 'Toshkent shahri',      name_ru = 'Город Ташкент'             WHERE full_code = 'UZ-13';
UPDATE geo_region SET name_uz_lat = 'Toshkent viloyati',    name_ru = 'Ташкентская область'       WHERE full_code = 'UZ-14';
UPDATE geo_region SET name_uz_lat = 'Xorazm viloyati',      name_ru = 'Хорезмская область'        WHERE full_code = 'UZ-05';

-- Major cities — update both name_uz_lat and name_ru
UPDATE geo_city SET name_uz_lat = 'Toshkent',      name_ru = 'Ташкент'       WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'tashkent'  OR LOWER(name_en) = 'tashkent');
UPDATE geo_city SET name_uz_lat = 'Samarqand',     name_ru = 'Самарканд'     WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'samarkand' OR LOWER(name_en) = 'samarkand' OR LOWER(name_uz_lat) = 'samarqand');
UPDATE geo_city SET name_uz_lat = 'Namangan',      name_ru = 'Наманган'      WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'namangan'  OR LOWER(name_en) = 'namangan') AND name_ru IS DISTINCT FROM 'Наманган';
UPDATE geo_city SET name_uz_lat = 'Andijon',       name_ru = 'Андижан'       WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'andijan'   OR LOWER(name_en) = 'andijan'  OR LOWER(name_uz_lat) = 'andijon');
UPDATE geo_city SET name_uz_lat = 'Nukus',         name_ru = 'Нукус'         WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'nukus'     OR LOWER(name_en) = 'nukus');
UPDATE geo_city SET name_uz_lat = 'Buxoro',        name_ru = 'Бухара'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'bukhara'   OR LOWER(name_en) = 'bukhara'  OR LOWER(name_uz_lat) = 'buxoro');
UPDATE geo_city SET name_uz_lat = E'Farg''ona',    name_ru = 'Фергана'       WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'fergana'   OR LOWER(name_en) = 'fergana'  OR LOWER(name_uz_lat) LIKE 'farg%');
UPDATE geo_city SET name_uz_lat = 'Qarshi',        name_ru = 'Карши'         WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'karshi'    OR LOWER(name_en) = 'karshi'   OR LOWER(name_uz_lat) = 'qarshi');
UPDATE geo_city SET name_uz_lat = E'Qo''qon',     name_ru = 'Коканд'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'kokand'    OR LOWER(name_en) = 'kokand');
UPDATE geo_city SET name_uz_lat = E'Marg''ilon',   name_ru = 'Маргилан'      WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'margilan'  OR LOWER(name_en) = 'margilan');
UPDATE geo_city SET name_uz_lat = 'Chirchiq',      name_ru = 'Чирчик'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'chirchik'  OR LOWER(name_en) = 'chirchik' OR LOWER(name_uz_lat) = 'chirchiq');
UPDATE geo_city SET name_uz_lat = 'Jizzax',        name_ru = 'Джизак'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'jizzakh'   OR LOWER(name_en) = 'jizzakh'  OR LOWER(name_uz_lat) = 'jizzax');
UPDATE geo_city SET name_uz_lat = 'Urganch',       name_ru = 'Ургенч'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'urgench'   OR LOWER(name_en) = 'urgench'  OR LOWER(name_uz_lat) = 'urganch');
UPDATE geo_city SET name_uz_lat = 'Navoiy',        name_ru = 'Навои'         WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'navoi'     OR LOWER(name_en) = 'navoi'    OR LOWER(name_uz_lat) = 'navoiy');
UPDATE geo_city SET name_uz_lat = 'Termiz',        name_ru = 'Термез'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'termez'    OR LOWER(name_en) = 'termez'   OR LOWER(name_uz_lat) = 'termiz');
UPDATE geo_city SET name_uz_lat = 'Angren',        name_ru = 'Ангрен'        WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'angren'    OR LOWER(name_en) = 'angren');
UPDATE geo_city SET name_uz_lat = 'Olmaliq',       name_ru = 'Алмалык'       WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'almalyk'   OR LOWER(name_en) = 'almalyk'  OR LOWER(name_uz_lat) = 'olmaliq');
UPDATE geo_city SET name_uz_lat = 'Guliston',      name_ru = 'Гулистан'      WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'gulistan'  OR LOWER(name_en) = 'gulistan' OR LOWER(name_uz_lat) = 'guliston');
UPDATE geo_city SET name_uz_lat = 'Denov',         name_ru = 'Денау'         WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'denau'     OR LOWER(name_en) = 'denau'    OR LOWER(name_uz_lat) = 'denov');
UPDATE geo_city SET name_uz_lat = 'Shahrisabz',    name_ru = 'Шахрисабз'     WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'shahrisabz' OR LOWER(name_en) = 'shahrisabz');
UPDATE geo_city SET name_uz_lat = E'To''rtko''l',  name_ru = 'Турткуль'      WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'turtkul'   OR LOWER(name_en) = 'turtkul');
UPDATE geo_city SET name_uz_lat = 'Zarafshon',     name_ru = 'Зарафшан'      WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'zarafshan' OR LOWER(name_en) = 'zarafshan' OR LOWER(name_uz_lat) = 'zarafshon');
UPDATE geo_city SET name_uz_lat = 'Xiva',          name_ru = 'Хива'          WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'khiva'     OR LOWER(name_en) = 'khiva'    OR LOWER(name_uz_lat) = 'xiva');
UPDATE geo_city SET name_uz_lat = 'Bekobod',       name_ru = 'Бекабад'       WHERE country = 'UZ' AND (LOWER(name_uz_lat) = 'bekabad'   OR LOWER(name_en) = 'bekabad'  OR LOWER(name_uz_lat) = 'bekobod');
